import test from 'node:test';
import assert from 'node:assert/strict';
import { mapLimit } from '../src/map-limit.mjs';
test('maps ordinary values',async()=>{assert.deepEqual(await mapLimit([1,2],2,x=>x*2),[{status:'fulfilled',value:2},{status:'fulfilled',value:4}]);});
test('mapper errors are per-item results',async()=>{const failure=new Error('failed');const out=await mapLimit([0,1],1,x=>{if(x===0)throw failure;return x;});assert.equal(out[0].reason,failure);assert.equal(out[1].value,1);});
